WITH LATEST_QUOTE AS (SELECT A.TRADE_DATE, M.CSNAME, M.COMB_SYMBOL, A.OPEN_PRICE, A.HIGH_PRICE, A.LOW_PRICE, A.CLOSE_PRICE, A.CHG, A.CHG_PCT_DAY, A.TRADE_AMOUNT, A.TRADE_VOLUME, A.TOTAL_SHARES, ROW_NUMBER() OVER (PARTITION BY A.FIU_ID ORDER BY A.TRADE_DATE DESC) AS rn FROM VIEW_US_EOD_EXPR A JOIN AMERICAN_STOCK_MAIN M ON A.FIU_ID = M.FIU_ID WHERE M.CSNAME LIKE '%微软%' AND A.CLOSE_PRICE IS NOT NULL) SELECT TRADE_DATE AS `交易日期`, CSNAME AS `股票名称`, COMB_SYMBOL AS `股票代码`, ROUND(OPEN_PRICE, 2) AS `开盘价(美元)`, ROUND(HIGH_PRICE, 2) AS `最高价(美元)`, ROUND(LOW_PRICE, 2) AS `最低价(美元)`, ROUND(CLOSE_PRICE, 2) AS `收盘价(美元)`, ROUND(CHG, 2) AS `涨跌额(美元)`, ROUND(CHG_PCT_DAY, 2) AS `涨跌幅(%)`, ROUND(TRADE_AMOUNT / 100000000, 2) AS `成交额(亿美元)`, ROUND(TRADE_VOLUME / 1000000, 2) AS `成交量(百万股)`, ROUND(TOTAL_SHARES / 100000000, 2) AS `总股本(亿股)` FROM LATEST_QUOTE WHERE rn = 1 ORDER BY CLOSE_PRICE DESC LIMIT 1;
